const marketCache = new Map();

export async function evaluateTrade(trade, cfg, state) {
  // 1) 只看买入/卖出的成交，不看拆分合并
  if (trade.side !== 'BUY' && trade.side !== 'SELL') {
    return { follow: false, reason: `非买卖单（${trade.side}），跳过` };
  }

