  }
  if (cfg.maxTradeUsd > 0 && size > cfg.maxTradeUsd) {
    return { follow: false, reason: `成交额 ${usd(size)} 高于上限 ${usd(cfg.maxTradeUsd)}` };
  }

  // 3) 市场成交量过滤（冷门盘滑点大）
