import { getJson } from '../src/util.mjs';

const ADDR = '0x09e27c2cbcd98c7e821ef66b309506701dcf29de';
const BASE = 'https://data-api.polymarket.com';

const variants = [
  ['基线 /positions', `${BASE}/positions?user=${ADDR}`],
  ['status=CLOSED', `${BASE}/positions?user=${ADDR}&status=CLOSED`],
  ['closed=true', `${BASE}/positions?user=${ADDR}&closed=true`],
  ['sortBy=REALIZED_PNL', `${BASE}/positions?user=${ADDR}&sortBy=REALIZED_PNL&sortDirection=DESC`],
  ['/closed-positions', `${BASE}/closed-positions?user=${ADDR}`],
];

for (const [name, url] of variants) {
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(15000) });
    const txt = await res.text();
    let data = null;
    try { data = JSON.parse(txt); } catch { /* 非 JSON */ }
    const arr = Array.isArray(data) ? data : Array.isArray(data?.data) ? data.data : null;
    if (!arr) {
      console.log(`${name.padEnd(24)} HTTP ${res.status}  非数组响应: ${txt.slice(0, 120)}`);
      continue;
    }
    const realized = arr.filter((p) => Number(p.realizedPnl ?? 0) !== 0);
    const sumReal = arr.reduce((s, p) => s + Number(p.realizedPnl ?? 0), 0);
    console.log(
      `${name.padEnd(24)} HTTP ${res.status}  条数=${String(arr.length).padEnd(4)} ` +
      `有realizedPnl=${String(realized.length).padEnd(4)} 合计=$${sumReal.toFixed(2)}`,
    );
  } catch (e) {
    console.log(`${name.padEnd(24)} 失败 ${e.message}`);
  }
}
