{"content":"/**
 * 交易员战绩统计 —— 用官方 API 自己算，不信任何平台的标称值。
 *
 * 核心发现（实测）：
 *   /positions          → 返回【当前持仓】，cashPnl 是未实现浮亏，不能算战绩
 *   /closed-positions   → 返回【已平仓】，realizedPnl 是已落袋的钱，这才是战绩
 *   limit 参数硬上限 50，必须用 offset 翻页才能拿全量
 *
 * 所以「胜率 / 盈亏比 / 累计盈亏」只能从 /closed-positions 算。
 */
import { getJson } from './util.mjs';

const DATA_API = 'https://data-api.polymarket.com';

/** 单次请求最多返回多少条（实测 limit=100/200/500 都被压回 50）。 */
const HARD_LIMIT = 50;

/**
 * 拉取某个地址的全部已平仓记录。
 * @param {string} address 钱包地址
 * @param {number} maxPages 最多翻几页（默认 20 页 = 1000 笔，够用且不会被限流打死）
 */
export async function fetchClosedPositions(address, maxPages = 20) {
  const all = [];
  const seen = new Set();
  for (let page = 0; page < maxPages; page++) {
    const offset = page * HARD_LIMIT;
    const url =
      `${DATA_API}/closed-positions?user=${encodeURIComponent(address)}` +
      `&limit=${HARD_LIMIT}&offset=${offset}`;
    let batch;
    try {
      batch = await getJson(url);
    } catch (e) {
      // 翻页中途失败：已经拿到的部分照样返回，不整批报废
      return { rows: all, truncated: true, error: e.message };
    }
    if (!Array.isArray(batch) || batch.length === 0) break;

    let added = 0;
    for (const p of batch) {
      // 同一个 position 可能因为成交多笔被拆成多行，按 市场+结果 去重
      const key = `${p.conditionId}|${p.outcome}`;
      if (seen.has(key)) continue;
      seen.add(key);
      all.push(p);
      added++;
    }
    if (added === 0 && batch.length < HARD_LIMIT) break;
    if (batch.length < HARD_LIMIT) break;
    if (added === 0) break; // 整页都是重复，说明到底了
  }
  return { rows: all, truncated: all.length >= maxPages * HARD_LIMIT, error: null };
}

