 */","old_string":"/**
 * 单日亏损熔断。state 里记着当天已实现的净额，超线就返回一个"该停机"的信号。
 * 这是止损之外的第二道闸：止损看的是浮亏，熔断看的是当天已经亏出去多少。
 */
export function checkDailyLoss(cfg, state) {
  const limit = Number(cfg.maxDailyLossUsd ?? 0);
  if (!(limit > 0)) return { tripped: false };

  const today = new Date().toISOString().slice(0, 10);
  const counter = state?.dailyLoss;
  if (!counter || counter.date !== today) return { tripped: false };

  if (counter.amount >= limit) {
    return {
      tripped: true,
      reason: `今日累计亏损已达 $${counter.amount.toFixed(2)}，触及熔断线 $${limit.toFixed(2)}，自动停机`,
    };
  }
  return { tripped: false };
}

/** 记录今日亏损（供熔断判断）。 */
export function recordDailyLoss(state, amountUsd) {
  const today = new Date().toISOString().slice(0, 10);
  if (!state.dailyLoss || state.dailyLoss.date !== today) {
    state.dailyLoss = { date: today, amount: 0 };
  }
  state.dailyLoss.amount += Math.abs(Number(amountUsd ?? 0));
  return state.dailyLoss;
}"}

